import importlib.util
from pathlib import Path

import pytest

# Module has a hyphen in its filename, so we need importlib to import it.
_mod_path = Path(__file__).resolve().parent.parent / "install-rules.py"
_spec = importlib.util.spec_from_file_location("install_rules", _mod_path)
install_rules = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(install_rules)

OTHER_REPO = "https://github.com/someone-else/other-repo"


def write_rule(
    path: Path, *, version: str | None, managed_by: str | None = install_rules.MANAGED_BY, body: str = "content"
) -> None:
    frontmatter_lines = []
    if managed_by is not None:
        frontmatter_lines.append(f"managed-by: {managed_by}")
    if version is not None:
        frontmatter_lines.append(f'version: "{version}"')
    frontmatter = f"---\n{chr(10).join(frontmatter_lines)}\n---\n" if frontmatter_lines else ""
    path.write_text(f"{frontmatter}{body}\n")


# -- extract_frontmatter ---------------------------------------------------------


class TestExtractFrontmatter:
    def test_extracts_block(self):
        text = '---\npaths:\n  - "**/*.py"\nversion: "1.0.0"\n---\n# Title\n'
        assert install_rules.extract_frontmatter(text) == ["paths:", '  - "**/*.py"', 'version: "1.0.0"']

    def test_no_opening_delimiter(self):
        assert install_rules.extract_frontmatter("# No frontmatter\n") is None

    def test_no_closing_delimiter(self):
        assert install_rules.extract_frontmatter('---\nversion: "1.0.0"\n') is None

    def test_empty_frontmatter(self):
        assert install_rules.extract_frontmatter("---\n---\ncontent\n") == []


