class TestInstallRule:
    def test_installs_when_missing(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.0.0")

        result = install_rules.install_rule(rule, target)

        assert (target / "rule.md").read_text() == rule.read_text()
        assert "installed rule.md (1.0.0)" == result

    def test_updates_when_source_is_newer(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.1.0", body="new content")
        write_rule(target / "rule.md", version="1.0.0", body="old content")

        result = install_rules.install_rule(rule, target)

        assert (target / "rule.md").read_text() == rule.read_text()
        assert result == "updated rule.md: 1.0.0 -> 1.1.0"

    def test_skips_when_up_to_date(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.0.0", body="new content")
        target_rule = target / "rule.md"
        write_rule(target_rule, version="1.0.0", body="old content")
        original_content = target_rule.read_text()

        result = install_rules.install_rule(rule, target)

        assert target_rule.read_text() == original_content
        assert result == "up to date rule.md (1.0.0)"

    def test_skips_when_target_has_no_managed_by(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.0.0")
        (target / "rule.md").write_text("hand-written content\n")

        result = install_rules.install_rule(rule, target)

        assert (target / "rule.md").read_text() == "hand-written content\n"
        assert result == "skipped rule.md: not managed by this repo, not overwriting"

    def test_skips_when_target_has_different_managed_by(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.0.0")
        target_rule = target / "rule.md"
        write_rule(target_rule, version="99.0.0", managed_by=OTHER_REPO, body="foreign content")

        result = install_rules.install_rule(rule, target)

        assert target_rule.read_text() == f'---\nmanaged-by: {OTHER_REPO}\nversion: "99.0.0"\n---\nforeign content\n'
        assert result == "skipped rule.md: not managed by this repo, not overwriting"

    def test_updates_when_managed_but_version_unparseable(self, tmp_path):
        source = tmp_path / "source"
        source.mkdir()
        target = tmp_path / "target"
        target.mkdir()

        rule = source / "rule.md"
        write_rule(rule, version="1.0.0")
        target_rule = target / "rule.md"
        write_rule(target_rule, version=None, body="corrupted")

        result = install_rules.install_rule(rule, target)

        assert target_rule.read_text() == rule.read_text()
        assert result == "updated rule.md: unknown -> 1.0.0"


