class TestReplaceStaleSymlink:
    def test_removes_symlink_without_touching_its_target(self, tmp_path):
        old_plugin_rules = tmp_path / "old-plugin-rules"
        old_plugin_rules.mkdir()
        (old_plugin_rules / "python.md").write_text("original plugin content\n")

        target_dir = tmp_path / "project" / ".claude" / "rules" / "plugins" / "nicecode" / "core"
        target_dir.parent.mkdir(parents=True)
        target_dir.symlink_to(old_plugin_rules)

        install_rules.replace_stale_symlink(target_dir)

        assert not target_dir.is_symlink()
        assert not target_dir.exists()
        assert (old_plugin_rules / "python.md").read_text() == "original plugin content\n"

    def test_noop_for_real_directory(self, tmp_path):
        target_dir = tmp_path / "target"
        target_dir.mkdir()

        install_rules.replace_stale_symlink(target_dir)

        assert target_dir.is_dir()
        assert not target_dir.is_symlink()


