    def test_migrates_stale_directory_symlink_from_old_installation(self, tmp_path, monkeypatch):
        plugin_root = tmp_path / "plugin"
        (plugin_root / "rules").mkdir(parents=True)
        write_rule(plugin_root / "rules" / "a.md", version="1.0.0")

        old_plugin_rules = tmp_path / "old-plugin-version" / "rules"
        old_plugin_rules.mkdir(parents=True)
        (old_plugin_rules / "a.md").write_text("stale plugin content\n")

        project_dir = tmp_path / "project"
        target_dir = project_dir / ".claude" / "rules" / "plugins" / "nicecode" / "core"
        target_dir.parent.mkdir(parents=True)
        target_dir.symlink_to(old_plugin_rules)

        monkeypatch.setattr(install_rules, "__file__", str(plugin_root / "scripts" / "install-rules.py"))
        monkeypatch.setattr("sys.argv", ["install-rules.py", str(project_dir), "--scope", "project"])

        install_rules.main()

        assert not target_dir.is_symlink()
        assert target_dir.is_dir()
        assert (target_dir / "a.md").read_text() == (plugin_root / "rules" / "a.md").read_text()
        assert (old_plugin_rules / "a.md").read_text() == "stale plugin content\n"
